#!/usr/bin/env bash
# Generate tar test fixtures under testdata/tar/ using GNU tar 1.35.
#
# Reproducible: `tar -cf` output depends only on input bytes and order (mtime
# fields are zeroed with --mtime, --owner/--group normalize uid/gid).
set -euo pipefail

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
TARDIR="$SCRIPT_DIR/../tar"
mkdir -p "$TARDIR"
OUT="$(cd "$TARDIR" && pwd)"
cd "$OUT"
rm -f ./*.tar ./*.tar.gz ./*.tgz ./*.tar.xz

mkdir -p "$TMP/build/dir"
printf 'Hello, hajizip!\n' > "$TMP/build/a.txt"
printf 'nested content\n' > "$TMP/build/dir/b.txt"

ZERO=(--mtime=@0 --owner=0 --group=0 --numeric-owner)

# --- basic.tar ---------------------------------------------------------------
(cd "$TMP/build" && tar "${ZERO[@]}" -cf "$OUT/basic.tar" a.txt dir)

# --- basic.tar.gz / hello.tgz: gzip-compressed tar ---------------------------
gzip -n -9 -c "$OUT/basic.tar" > "$OUT/basic.tar.gz"
cp "$OUT/basic.tar.gz" "$OUT/hello.tgz"

# --- basic.tar.xz: xz-compressed tar -----------------------------------------
xz -9 -c "$OUT/basic.tar" > "$OUT/basic.tar.xz"

# --- long.tar: names > 100 chars (PAX/GNU extension) -------------------------
DEEP="deep/$(printf 'x%.0s' $(seq 1 60))/$(printf 'y%.0s' $(seq 1 50)).txt"
mkdir -p "$TMP/build/deep/$(printf 'x%.0s' $(seq 1 60))"
printf 'deep\n' > "$TMP/build/$DEEP"
(cd "$TMP/build" && tar "${ZERO[@]}" -cf "$OUT/long.tar" "$DEEP")

# --- sym.tar: symlink entry --------------------------------------------------
ln -sf /etc/passwd "$TMP/build/link"
(cd "$TMP/build" && tar "${ZERO[@]}" -cf "$OUT/sym.tar" link)

# --- abs.tar: absolute path (must be normalized to relative on listing) ------
# The stored name keeps an absolute prefix (raw bytes start with `/`); a
# `--transform` rewrites the tmpdir part so regeneration is byte-deterministic.
(cd "$TMP" && tar "${ZERO[@]}" --absolute-names \
    --transform='s|^/tmp/[^/]*/build/|/archive/build/|' \
    -cf "$OUT/abs.tar" "$TMP/build/a.txt")

# --- slip.tar: entry with a `..` component -----------------------------------
printf 'evil\n' > "$TMP/build/evil.txt"
# GNU tar strips leading `../` by default; --transform re-injects it after the
# source path is resolved, so the stored name keeps the `..` component.
(cd "$TMP/build" && tar "${ZERO[@]}" --transform='s|^evil\.txt$|../evil.txt|' \
    -cf "$OUT/slip.tar" evil.txt)

# --- nested.tar: contains tar, tar.gz and zip ---------------------------------
mkdir -p "$TMP/n"
cp "$OUT/basic.tar" "$TMP/n/inner.tar"
cp "$OUT/basic.tar.gz" "$TMP/n/inner.tar.gz"
cp "$SCRIPT_DIR/../zip/basic.zip" "$TMP/n/inner.zip"
(cd "$TMP/n" && tar "${ZERO[@]}" -cf "$OUT/nested.tar" inner.tar inner.tar.gz inner.zip)

# --- empty.tar: two zero blocks ----------------------------------------------
: > "$TMP/empty.bin"
dd if=/dev/zero of="$OUT/empty.tar" bs=512 count=2 2>/dev/null

# --- many.tar: 10 000 small entries -------------------------------------------
mkdir -p "$TMP/m"
for i in $(seq 1 10000); do printf x > "$TMP/m/f$i"; done
(cd "$TMP/m" && tar "${ZERO[@]}" -cf "$OUT/many.tar" f*)

# --- manifest -----------------------------------------------------------------
cat > manifest.toml <<'EOF'
# Tar fixtures. Generated by testdata/gen/gen-tar.sh (GNU tar 1.35,
# --mtime=@0 --owner=0 --group=0). `name` lists entry names (tar -tf output).

[basic.tar]
name = ["a.txt", "dir/", "dir/b.txt"]

[basic.tar.gz]
name = ["a.txt", "dir/", "dir/b.txt"]
note = "gzip-compressed tar"

[hello.tgz]
name = ["a.txt", "dir/", "dir/b.txt"]
note = "same content as basic.tar.gz, .tgz extension"

[basic.tar.xz]
name = ["a.txt", "dir/", "dir/b.txt"]
note = "xz-compressed tar (M2)"

[long.tar]
name = ["deep/xxx.../yyy....txt"]
note = "entry name > 100 chars (PAX/GNU long-name extension)"

[sym.tar]
name = ["link"]
note = "symlink entry pointing outside the archive"

[abs.tar]
name = ["<abs path>"]
note = "absolute path entry; must be normalized to a relative path"

[slip.tar]
name = ["../evil.txt"]
note = "entry with `..` component must be skipped at listing"

[nested.tar]
name = ["inner.tar", "inner.tar.gz", "inner.zip"]
note = "nested archives of each supported kind"

[empty.tar]
name = []
note = "two zero blocks (no entries)"

[many.tar]
name_count = 10000
note = "10 000 small entries"
EOF

echo "generated:"
ls -l ./*.tar ./*.tar.gz ./*.tgz ./*.tar.xz
